insert into items (id, skill_id, hub, difficulty, body, options, answer, solution, wrong_option_errors)
values
  ('counting-based-probability--2-1', 'counting-based-probability', 'eysh', 1, 'A committee of $2$ is chosen at random from $3$ boys and $2$ girls. Find the probability that both are girls.', '{"A": "$\\dfrac{1}{10}$", "B": "$\\dfrac{2}{5}$", "C": "$\\dfrac{1}{5}$", "D": "$\\dfrac{3}{10}$"}'::jsonb, 'A', 'There is $\binom{2}{2}=1$ way to choose both girls out of $\binom{5}{2}=10$ committees, so $P=\dfrac{1}{10}$.', '{"B": "used the proportion of girls, $\\tfrac{2}{5}$, ignoring that two are drawn", "C": "divided by $5$ instead of $\\binom{5}{2}$", "D": "counted ordered pairs on top but unordered below"}'::jsonb),
  ('counting-based-probability--3-2', 'counting-based-probability', 'eysh', 2, 'Three balls are drawn at random from a bag holding $5$ red and $4$ blue. Find the probability that exactly two are red.', '{"A": "$\\dfrac{10}{21}$", "B": "$\\dfrac{5}{42}$", "C": "$\\dfrac{5}{21}$", "D": "$\\dfrac{2}{7}$"}'::jsonb, 'A', '$\dfrac{\binom{5}{2}\binom{4}{1}}{\binom{9}{3}} = \dfrac{10 \cdot 4}{84} = \dfrac{10}{21}$.', '{"B": "forgot to choose the third ball from the blues", "C": "chose two blues instead of one", "D": "used $\\binom{4}{2}$ for the blue ball"}'::jsonb),
  ('counting-based-probability--4-3', 'counting-based-probability', 'eysh', 3, 'The letters $A$, $B$, $C$, $D$ are arranged at random in a row. Find the probability that $A$ stands immediately before $B$.', '{"A": "$\\dfrac{1}{4}$", "B": "$\\dfrac{1}{2}$", "C": "$\\dfrac{1}{12}$", "D": "$\\dfrac{1}{3}$"}'::jsonb, 'A', 'Glue $AB$ into one block: $3! = 6$ arrangements out of $4! = 24$, so $P = \dfrac{6}{24} = \dfrac{1}{4}$.', '{"B": "answered ''$A$ somewhere before $B$'', which is $\\tfrac12$", "C": "counted only $2$ favourable arrangements", "D": "divided the four positions rather than counting arrangements"}'::jsonb),
  ('independent-events--2-1', 'independent-events', 'eysh', 1, '$A$ and $B$ are independent with $P(A)=0.6$ and $P(B)=0.5$. Find $P(A \cap B)$.', '{"A": "$0.3$", "B": "$1.1$", "C": "$0.1$", "D": "$0.8$"}'::jsonb, 'A', 'For independent events $P(A \cap B) = P(A)P(B) = 0.6 \times 0.5 = 0.3$.', '{"B": "added the probabilities", "C": "subtracted the probabilities", "D": "computed the union instead of the intersection"}'::jsonb),
  ('independent-events--3-2', 'independent-events', 'eysh', 2, 'A fair coin is tossed three times. Find the probability of at least one head.', '{"A": "$\\dfrac{7}{8}$", "B": "$\\dfrac{1}{8}$", "C": "$\\dfrac{1}{2}$", "D": "$\\dfrac{3}{8}$"}'::jsonb, 'A', '$P(\text{no head}) = \left(\tfrac12\right)^3 = \tfrac18$, so $P(\text{at least one}) = 1 - \tfrac18 = \tfrac78$.', '{"B": "gave the probability of no heads", "C": "answered for a single toss", "D": "gave the probability of exactly one head"}'::jsonb),
  ('independent-events--4-3', 'independent-events', 'eysh', 3, '$A$ and $B$ are independent, $P(A)=0.4$ and $P(A \cup B)=0.7$. Find $P(B)$.', '{"A": "$0.5$", "B": "$0.3$", "C": "$0.75$", "D": "$0.42$"}'::jsonb, 'A', '$P(A \cup B) = P(A) + P(B) - P(A)P(B)$, so $0.7 = 0.4 + 0.6\,P(B)$ and $P(B) = 0.5$.', '{"B": "treated the events as mutually exclusive", "C": "divided $0.3$ by $0.4$", "D": "multiplied instead of solving"}'::jsonb),
  ('sample-space-and-events--2-1', 'sample-space-and-events', 'eysh', 1, 'Two fair dice are thrown. How many outcomes are in the sample space?', '{"A": "$36$", "B": "$12$", "C": "$6$", "D": "$21$"}'::jsonb, 'A', 'Each die has $6$ faces and the throws are separate, so $6 \times 6 = 36$.', '{"B": "added the two dice", "C": "counted one die only", "D": "counted unordered pairs"}'::jsonb),
  ('sample-space-and-events--3-2', 'sample-space-and-events', 'eysh', 2, 'Two fair dice are thrown. Find the probability that the total is $7$.', '{"A": "$\\dfrac{1}{6}$", "B": "$\\dfrac{5}{36}$", "C": "$\\dfrac{7}{36}$", "D": "$\\dfrac{1}{12}$"}'::jsonb, 'A', 'Six of the $36$ outcomes total $7$, so $P = \dfrac{6}{36} = \dfrac16$.', '{"B": "counted five favourable outcomes", "C": "used the total as the count", "D": "counted only three favourable outcomes"}'::jsonb),
  ('sample-space-and-events--4-3', 'sample-space-and-events', 'eysh', 3, 'A coin is tossed until a head appears or three tosses have been made. How many outcomes are in the sample space?', '{"A": "$4$", "B": "$8$", "C": "$3$", "D": "$6$"}'::jsonb, 'A', 'The outcomes are $H$, $TH$, $TTH$ and $TTT$ — the process stops early on a head, so there are $4$, not $2^3$.', '{"B": "counted all three-toss sequences, ignoring the stopping rule", "C": "forgot the all-tails outcome", "D": "counted tosses rather than outcomes"}'::jsonb),
  ('triangle-angle-sum--2-1', 'triangle-angle-sum', 'eysh', 1, 'Two angles of a triangle are $47^{\circ}$ and $68^{\circ}$. Find the third.', '{"A": "$65^{\\circ}$", "B": "$115^{\\circ}$", "C": "$85^{\\circ}$", "D": "$45^{\\circ}$"}'::jsonb, 'A', '$180^{\circ} - 47^{\circ} - 68^{\circ} = 65^{\circ}$.', '{"B": "gave the sum of the two known angles", "C": "used $200^{\\circ}$ as the angle sum", "D": "used $160^{\\circ}$ as the angle sum"}'::jsonb),
  ('triangle-angle-sum--3-2', 'triangle-angle-sum', 'eysh', 2, 'In an isosceles triangle the apex angle is $34^{\circ}$. Find one base angle.', '{"A": "$73^{\\circ}$", "B": "$146^{\\circ}$", "C": "$56^{\\circ}$", "D": "$63^{\\circ}$"}'::jsonb, 'A', 'The two base angles are equal: $\dfrac{180^{\circ}-34^{\circ}}{2} = 73^{\circ}$.', '{"B": "gave the sum of both base angles", "C": "took the complement of the apex angle", "D": "halved $180^{\\circ}$ then subtracted $27^{\\circ}$"}'::jsonb),
  ('triangle-angle-sum--4-3', 'triangle-angle-sum', 'eysh', 3, 'An exterior angle of a triangle is $115^{\circ}$ and one of the two non-adjacent interior angles is $42^{\circ}$. Find the other.', '{"A": "$73^{\\circ}$", "B": "$23^{\\circ}$", "C": "$65^{\\circ}$", "D": "$138^{\\circ}$"}'::jsonb, 'A', 'An exterior angle equals the sum of the two non-adjacent interior angles, so the other is $115^{\circ} - 42^{\circ} = 73^{\circ}$.', '{"B": "subtracted from the adjacent interior angle instead", "C": "gave the adjacent interior angle", "D": "subtracted $42^{\\circ}$ from $180^{\\circ}$"}'::jsonb),
  ('factoring-quadratic-trinomial--2-1', 'factoring-quadratic-trinomial', 'eysh', 1, 'Factorise $x^{2} + 9x + 20$.', '{"A": "$(x+4)(x+5)$", "B": "$(x+2)(x+10)$", "C": "$(x-4)(x-5)$", "D": "$(x+1)(x+20)$"}'::jsonb, 'A', 'Two numbers with product $20$ and sum $9$: $4$ and $5$.', '{"B": "product correct, sum is $12$", "C": "right numbers, wrong signs", "D": "product correct, sum is $21$"}'::jsonb),
  ('factoring-quadratic-trinomial--3-2', 'factoring-quadratic-trinomial', 'eysh', 2, 'Factorise $2x^{2} - 7x + 3$.', '{"A": "$(2x-1)(x-3)$", "B": "$(2x-3)(x-1)$", "C": "$(2x+1)(x+3)$", "D": "$(x-1)(x-3)$"}'::jsonb, 'A', 'Split $-7x$ as $-x - 6x$: $2x^{2} - x - 6x + 3 = x(2x-1) - 3(2x-1) = (2x-1)(x-3)$.', '{"B": "swapped the constants — this expands to $-5x$", "C": "both signs wrong", "D": "dropped the leading coefficient"}'::jsonb),
  ('factoring-quadratic-trinomial--4-3', 'factoring-quadratic-trinomial', 'eysh', 3, 'Factorise $6x^{2} + x - 12$.', '{"A": "$(3x-4)(2x+3)$", "B": "$(3x+4)(2x-3)$", "C": "$(6x-4)(x+3)$", "D": "$(3x-2)(2x+6)$"}'::jsonb, 'A', 'Find two numbers with product $6 \cdot (-12) = -72$ and sum $1$: $9$ and $-8$. Then $6x^{2} + 9x - 8x - 12 = 3x(2x+3) - 4(2x+3) = (3x-4)(2x+3)$.', '{"B": "signs swapped — this gives the middle term $-x$", "C": "expands to $6x^{2}+14x-12$", "D": "expands to $6x^{2}+14x-12$ as well"}'::jsonb),
  ('area-under-curve--2-1', 'area-under-curve', 'eysh', 1, 'Find the area between $y = x^{2}$ and the $x$-axis from $x=0$ to $x=3$.', '{"A": "$9$", "B": "$27$", "C": "$3$", "D": "$18$"}'::jsonb, 'A', '$\displaystyle\int_{0}^{3} x^{2}\,dx = \left[\tfrac{x^{3}}{3}\right]_{0}^{3} = 9$.', '{"B": "forgot to divide by $3$", "C": "evaluated the integrand at $x=3$... then divided by $9$", "D": "used $\\tfrac{x^{3}}{3}$ but doubled it"}'::jsonb),
  ('area-under-curve--3-2', 'area-under-curve', 'eysh', 2, 'Find the area enclosed between $y = 4 - x^{2}$ and the $x$-axis.', '{"A": "$\\dfrac{32}{3}$", "B": "$\\dfrac{16}{3}$", "C": "$16$", "D": "$8$"}'::jsonb, 'A', 'The curve meets the axis at $x = \pm 2$, so the area is $\displaystyle\int_{-2}^{2}(4-x^{2})\,dx = \dfrac{32}{3}$.', '{"B": "integrated from $0$ to $2$ only", "C": "used the rectangle $4 \\times 4$", "D": "used $\\tfrac12 \\times 4 \\times 4$"}'::jsonb),
  ('area-under-curve--4-3', 'area-under-curve', 'eysh', 3, 'Find the total area between $y = x^{2} - 4$ and the $x$-axis from $x=0$ to $x=3$.', '{"A": "$\\dfrac{23}{3}$", "B": "$-3$", "C": "$\\dfrac{16}{3}$", "D": "$\\dfrac{7}{3}$"}'::jsonb, 'A', 'The curve is below the axis on $[0,2]$ and above on $[2,3]$, so the AREA is $\left|\int_{0}^{2}\right| + \int_{2}^{3} = \dfrac{16}{3} + \dfrac{7}{3} = \dfrac{23}{3}$.', '{"B": "integrated straight through — the signed value, not the area", "C": "took only the part below the axis", "D": "took only the part above the axis"}'::jsonb),
  ('chain-rule--2-1', 'chain-rule', 'eysh', 1, 'Differentiate $y = (3x + 1)^{4}$.', '{"A": "$12(3x+1)^{3}$", "B": "$4(3x+1)^{3}$", "C": "$12(3x+1)^{4}$", "D": "$3(3x+1)^{3}$"}'::jsonb, 'A', '$4(3x+1)^{3} \cdot 3 = 12(3x+1)^{3}$.', '{"B": "forgot the derivative of the inside", "C": "did not reduce the power", "D": "used only the inside derivative"}'::jsonb),
  ('chain-rule--3-2', 'chain-rule', 'eysh', 2, 'Differentiate $y = \sqrt{x^{2}+9}$.', '{"A": "$\\dfrac{x}{\\sqrt{x^{2}+9}}$", "B": "$\\dfrac{1}{2\\sqrt{x^{2}+9}}$", "C": "$\\dfrac{2x}{\\sqrt{x^{2}+9}}$", "D": "$\\dfrac{x}{2\\sqrt{x^{2}+9}}$"}'::jsonb, 'A', '$\dfrac{1}{2\sqrt{x^{2}+9}} \cdot 2x = \dfrac{x}{\sqrt{x^{2}+9}}$.', '{"B": "forgot the inside derivative $2x$", "C": "did not cancel the $2$", "D": "cancelled the $2$ from the wrong place"}'::jsonb),
  ('chain-rule--4-3', 'chain-rule', 'eysh', 3, 'Differentiate $y = \sin^{3}(2x)$.', '{"A": "$6\\sin^{2}(2x)\\cos(2x)$", "B": "$3\\sin^{2}(2x)\\cos(2x)$", "C": "$6\\sin^{2}(2x)$", "D": "$3\\cos^{3}(2x)$"}'::jsonb, 'A', 'Two layers: $3\sin^{2}(2x) \cdot \cos(2x) \cdot 2 = 6\sin^{2}(2x)\cos(2x)$.', '{"B": "missed the innermost factor $2$", "C": "did not differentiate the sine", "D": "differentiated the power and the sine together"}'::jsonb),
  ('derivative-product-quotient--2-1', 'derivative-product-quotient', 'eysh', 1, 'Differentiate $y = x^{2}\,e^{x}$.', '{"A": "$(x^{2}+2x)e^{x}$", "B": "$2xe^{x}$", "C": "$(x^{2}-2x)e^{x}$", "D": "$2x e^{x} + x^{2}$"}'::jsonb, 'A', '$2x\,e^{x} + x^{2}e^{x} = (x^{2}+2x)e^{x}$.', '{"B": "differentiated the two factors separately and multiplied", "C": "sign error in the product rule", "D": "did not differentiate $e^{x}$ in the second term"}'::jsonb),
  ('derivative-product-quotient--3-2', 'derivative-product-quotient', 'eysh', 2, 'Differentiate $y = \dfrac{x}{x+1}$.', '{"A": "$\\dfrac{1}{(x+1)^{2}}$", "B": "$\\dfrac{-1}{(x+1)^{2}}$", "C": "$1$", "D": "$\\dfrac{2x+1}{(x+1)^{2}}$"}'::jsonb, 'A', '$\dfrac{(1)(x+1) - x(1)}{(x+1)^{2}} = \dfrac{1}{(x+1)^{2}}$.', '{"B": "subtracted the quotient-rule terms the wrong way round", "C": "differentiated numerator and denominator separately", "D": "added the terms in the numerator instead of subtracting"}'::jsonb),
  ('derivative-product-quotient--4-3', 'derivative-product-quotient', 'eysh', 3, 'Find $f''(1)$ for $f(x) = \dfrac{x^{2}-1}{x^{2}+1}$.', '{"A": "$1$", "B": "$0$", "C": "$\\dfrac{1}{2}$", "D": "$2$"}'::jsonb, 'A', '$f''(x) = \dfrac{4x}{(x^{2}+1)^{2}}$, so $f''(1) = \dfrac{4}{4} = 1$.', '{"B": "substituted into $f$ rather than $f''$", "C": "forgot to square the denominator", "D": "left the numerator as $4x$ over $2$"}'::jsonb),
  ('domain-of-a-function--2-1', 'domain-of-a-function', 'eysh', 1, 'Find the domain of $f(x) = \dfrac{1}{x-3}$.', '{"A": "$x \\ne 3$", "B": "$x > 3$", "C": "$x \\ne 0$", "D": "$x \\ge 3$"}'::jsonb, 'A', 'The denominator vanishes at $x = 3$, so every real $x$ except $3$ is allowed.', '{"B": "applied a square-root condition to a fraction", "C": "excluded the wrong value", "D": "included the excluded point"}'::jsonb),
  ('domain-of-a-function--3-2', 'domain-of-a-function', 'eysh', 2, 'Find the domain of $f(x) = \sqrt{2x - 6}$.', '{"A": "$x \\ge 3$", "B": "$x > 3$", "C": "$x \\ge -3$", "D": "$x \\le 3$"}'::jsonb, 'A', 'Need $2x - 6 \ge 0$, so $x \ge 3$. Equality is allowed because $\sqrt{0}$ is defined.', '{"B": "excluded $x=3$, but $\\sqrt{0}=0$ is defined", "C": "sign error solving the inequality", "D": "reversed the inequality"}'::jsonb),
  ('domain-of-a-function--4-3', 'domain-of-a-function', 'eysh', 3, 'Find the domain of $f(x) = \dfrac{\sqrt{x+2}}{x-1}$.', '{"A": "$x \\ge -2,\\ x \\ne 1$", "B": "$x \\ge -2$", "C": "$x > 1$", "D": "$x \\ne 1$"}'::jsonb, 'A', 'Two conditions at once: $x + 2 \ge 0$ gives $x \ge -2$, and $x - 1 \ne 0$ removes $x = 1$.', '{"B": "checked the root but not the denominator", "C": "over-restricted by requiring both to be positive", "D": "checked the denominator but not the root"}'::jsonb),
  ('circle-area-and-arc--2-1', 'circle-area-and-arc', 'eysh', 1, 'A circle has circumference $10\pi$. Find its area.', '{"A": "$25\\pi$", "B": "$100\\pi$", "C": "$10\\pi$", "D": "$5\\pi$"}'::jsonb, 'A', '$2\pi r = 10\pi$ gives $r = 5$, so $A = \pi r^{2} = 25\pi$.', '{"B": "used the circumference as the radius", "C": "returned the circumference", "D": "used $\\pi r$ instead of $\\pi r^{2}$"}'::jsonb),
  ('circle-area-and-arc--3-2', 'circle-area-and-arc', 'eysh', 2, 'Find the length of an arc subtending $60^{\circ}$ at the centre of a circle of radius $9$.', '{"A": "$3\\pi$", "B": "$6\\pi$", "C": "$\\dfrac{27\\pi}{2}$", "D": "$18\\pi$"}'::jsonb, 'A', '$\dfrac{60}{360} \times 2\pi(9) = \dfrac16 \times 18\pi = 3\pi$.', '{"B": "used $\\tfrac13$ of the circumference", "C": "computed the sector AREA instead of the arc length", "D": "gave the whole circumference"}'::jsonb),
  ('circle-area-and-arc--4-3', 'circle-area-and-arc', 'eysh', 3, 'A sector of a circle of radius $6$ has area $12\pi$. Find its angle at the centre.', '{"A": "$120^{\\circ}$", "B": "$60^{\\circ}$", "C": "$240^{\\circ}$", "D": "$90^{\\circ}$"}'::jsonb, 'A', 'The whole circle has area $36\pi$, so the sector is $\dfrac{12\pi}{36\pi} = \dfrac13$ of it: $\dfrac13 \times 360^{\circ} = 120^{\circ}$.', '{"B": "took the sector as one sixth of the circle", "C": "used two thirds instead of one third", "D": "assumed a quarter circle"}'::jsonb),
  ('circle-equation--2-1', 'circle-equation', 'eysh', 1, 'Find the centre and radius of $(x-2)^{2} + (y+3)^{2} = 16$.', '{"A": "centre $(2,-3)$, radius $4$", "B": "centre $(-2,3)$, radius $4$", "C": "centre $(2,-3)$, radius $16$", "D": "centre $(-2,3)$, radius $16$"}'::jsonb, 'A', 'Read the signs off the brackets: centre $(2,-3)$, and the radius is $\sqrt{16} = 4$.', '{"B": "read both signs the wrong way", "C": "used $r^{2}$ as the radius", "D": "both errors together"}'::jsonb),
  ('circle-equation--3-2', 'circle-equation', 'eysh', 2, 'Find the radius of the circle $x^{2} + y^{2} - 6x + 4y - 12 = 0$.', '{"A": "$5$", "B": "$\\sqrt{12}$", "C": "$25$", "D": "$\\sqrt{13}$"}'::jsonb, 'A', 'Completing the square: $(x-3)^{2} + (y+2)^{2} = 12 + 9 + 4 = 25$, so $r = 5$.', '{"B": "took the constant term without completing the square", "C": "gave $r^{2}$", "D": "added $9$ and $4$ but forgot the $12$"}'::jsonb),
  ('circle-equation--4-3', 'circle-equation', 'eysh', 3, 'A circle has centre $(1,2)$ and passes through $(4,6)$. Find its equation.', '{"A": "$(x-1)^{2}+(y-2)^{2}=25$", "B": "$(x-1)^{2}+(y-2)^{2}=5$", "C": "$(x+1)^{2}+(y+2)^{2}=25$", "D": "$(x-4)^{2}+(y-6)^{2}=25$"}'::jsonb, 'A', '$r^{2} = (4-1)^{2} + (6-2)^{2} = 9 + 16 = 25$.', '{"B": "used the radius instead of its square on the right", "C": "wrong signs in the brackets", "D": "used the point on the circle as the centre"}'::jsonb),
  ('pythagoras--2-1', 'pythagoras', 'eysh', 1, 'A right-angled triangle has hypotenuse $10$ and one leg $6$. Find the other leg.', '{"A": "$8$", "B": "$4$", "C": "$\\sqrt{136}$", "D": "$16$"}'::jsonb, 'A', '$\sqrt{10^{2} - 6^{2}} = \sqrt{64} = 8$.', '{"B": "subtracted the lengths instead of the squares", "C": "added the squares — but $10$ is the hypotenuse", "D": "forgot the square root"}'::jsonb),
  ('pythagoras--3-2', 'pythagoras', 'eysh', 2, 'Is a triangle with sides $9$, $12$, $15$ right-angled?', '{"A": "Yes, the right angle is opposite the side $15$", "B": "Yes, the right angle is opposite the side $9$", "C": "No, because $9 + 12 \\ne 15$", "D": "No, because $9^{2}+12^{2} \\ne 15^{2}$"}'::jsonb, 'A', '$9^{2} + 12^{2} = 81 + 144 = 225 = 15^{2}$, so it is right-angled, with the right angle opposite the longest side.', '{"B": "put the right angle opposite the shortest side", "C": "tested the sides rather than their squares", "D": "arithmetic slip — the two sides do agree"}'::jsonb),
  ('pythagoras--4-3', 'pythagoras', 'eysh', 3, 'A rectangular box measures $3 \times 4 \times 12$. Find the length of its space diagonal.', '{"A": "$13$", "B": "$5$", "C": "$19$", "D": "$\\sqrt{160}$"}'::jsonb, 'A', '$\sqrt{3^{2}+4^{2}+12^{2}} = \sqrt{9+16+144} = \sqrt{169} = 13$.', '{"B": "found the diagonal of the base only", "C": "added the three edges", "D": "used $3^{2}+12^{2}+\\ldots$ with a slip"}'::jsonb),
  ('triangle-area--2-1', 'triangle-area', 'eysh', 1, 'Find the area of a triangle with base $14$ and perpendicular height $9$.', '{"A": "$63$", "B": "$126$", "C": "$23$", "D": "$31.5$"}'::jsonb, 'A', '$\tfrac12 \times 14 \times 9 = 63$.', '{"B": "forgot the factor $\\tfrac12$", "C": "added base and height", "D": "halved twice"}'::jsonb),
  ('triangle-area--3-2', 'triangle-area', 'eysh', 2, 'Find the area of a triangle with sides $8$ and $10$ enclosing an angle of $30^{\circ}$.', '{"A": "$20$", "B": "$40$", "C": "$20\\sqrt{3}$", "D": "$80$"}'::jsonb, 'A', '$\tfrac12 ab\sin C = \tfrac12(8)(10)\sin 30^{\circ} = 40 \times \tfrac12 = 20$.', '{"B": "omitted the $\\sin 30^{\\circ}$", "C": "used $\\sin 60^{\\circ}$", "D": "omitted both the $\\tfrac12$ and the sine"}'::jsonb),
  ('triangle-area--4-3', 'triangle-area', 'eysh', 3, 'A triangle has area $30$, and two of its sides are $12$ and $10$. Find the sine of the angle between them.', '{"A": "$\\dfrac{1}{2}$", "B": "$\\dfrac{1}{4}$", "C": "$\\dfrac{1}{\\sqrt{2}}$", "D": "$\\dfrac{5}{2}$"}'::jsonb, 'A', '$\tfrac12(12)(10)\sin C = 30$ gives $60\sin C = 30$, so $\sin C = \tfrac12$.', '{"B": "forgot the $\\tfrac12$ when rearranging", "C": "assumed a $45^{\\circ}$ angle", "D": "inverted the final division"}'::jsonb),
  ('triangle-similarity--2-1', 'triangle-similarity', 'eysh', 1, 'Triangles $ABC$ and $DEF$ are similar with $AB = 6$, $DE = 9$ and $BC = 8$. Find $EF$.', '{"A": "$12$", "B": "$11$", "C": "$\\dfrac{16}{3}$", "D": "$5.33$"}'::jsonb, 'A', 'The scale factor is $\dfrac96 = \dfrac32$, so $EF = 8 \times \dfrac32 = 12$.', '{"B": "added the difference $9-6=3$ instead of scaling", "C": "scaled by $\\tfrac23$ — the wrong way round", "D": "same inversion, written as a decimal"}'::jsonb),
  ('triangle-similarity--3-2', 'triangle-similarity', 'eysh', 2, 'In triangle $ABC$, $DE \parallel BC$ with $D$ on $AB$ and $E$ on $AC$. If $AD = 4$, $DB = 6$ and $AE = 6$, find $EC$.', '{"A": "$9$", "B": "$4$", "C": "$15$", "D": "$\\dfrac{8}{3}$"}'::jsonb, 'A', '$\dfrac{AD}{DB} = \dfrac{AE}{EC}$ gives $\dfrac46 = \dfrac{6}{EC}$, so $EC = 9$.', '{"B": "matched $AD$ to $AE$ and copied the difference", "C": "gave the whole side $AC$", "D": "inverted the ratio"}'::jsonb),
  ('triangle-similarity--4-3', 'triangle-similarity', 'eysh', 3, 'Two similar triangles have areas $27$ and $48$. The smaller has a side of length $9$. Find the corresponding side of the larger.', '{"A": "$12$", "B": "$16$", "C": "$\\dfrac{9\\sqrt{48}}{\\sqrt{27}}$ rounded to $11$", "D": "$\\dfrac{27}{4}$"}'::jsonb, 'A', 'Areas scale by the square of the length ratio, so the ratio is $\sqrt{\dfrac{48}{27}} = \dfrac43$ and the side is $9 \times \dfrac43 = 12$.', '{"B": "scaled by the area ratio $\\tfrac{48}{27}$ directly", "C": "correct method, arithmetic slip in the surd", "D": "scaled downwards"}'::jsonb),
  ('discriminant--2-1', 'discriminant', 'eysh', 1, 'How many real roots does $x^{2} - 4x + 7 = 0$ have?', '{"A": "none", "B": "one", "C": "two", "D": "two, both negative"}'::jsonb, 'A', '$\Delta = 16 - 28 = -12 < 0$, so there are no real roots.', '{"B": "treated $\\Delta<0$ as a repeated root", "C": "took $\\Delta = 16+28$", "D": "read the sign of $b$ as the sign of the roots"}'::jsonb),
  ('discriminant--3-2', 'discriminant', 'eysh', 2, 'For which value of $k$ does $x^{2} + kx + 9 = 0$ have exactly one real root, with $k > 0$?', '{"A": "$k = 6$", "B": "$k = 3$", "C": "$k = 9$", "D": "$k = 36$"}'::jsonb, 'A', 'One root means $\Delta = k^{2} - 36 = 0$, so $k = 6$ (taking $k>0$).', '{"B": "solved $k^{2}=9$", "C": "set $k$ equal to the constant term", "D": "solved $k = 36$ without the square root"}'::jsonb),
  ('discriminant--4-3', 'discriminant', 'eysh', 3, 'Find the values of $m$ for which $mx^{2} + 4x + 1 = 0$ has two distinct real roots ($m \ne 0$).', '{"A": "$m < 4,\\ m \\ne 0$", "B": "$m > 4$", "C": "$m < 4$", "D": "$m > 0$"}'::jsonb, 'A', '$\Delta = 16 - 4m > 0$ gives $m < 4$; and $m \ne 0$ or it is not a quadratic.', '{"B": "reversed the inequality when dividing by $-4$", "C": "correct inequality but forgot that $m=0$ is not allowed", "D": "used the sign of $m$ rather than the discriminant"}'::jsonb),
  ('factoring-common-factor--2-1', 'factoring-common-factor', 'eysh', 1, 'Factorise $12x^{3} - 18x^{2}$.', '{"A": "$6x^{2}(2x-3)$", "B": "$6x(2x^{2}-3x)$", "C": "$2x^{2}(6x-9)$", "D": "$6x^{2}(2x-3x)$"}'::jsonb, 'A', 'The highest common factor is $6x^{2}$, leaving $2x - 3$.', '{"B": "took out only $6x$", "C": "took out only the highest common power of $x$ with a factor of $2$", "D": "left an $x$ inside the bracket by mistake"}'::jsonb),
  ('factoring-common-factor--3-2', 'factoring-common-factor', 'eysh', 2, 'Factorise $5a(x-2) - 3(x-2)$.', '{"A": "$(x-2)(5a-3)$", "B": "$(x-2)(5a+3)$", "C": "$5a-3(x-2)$", "D": "$(x-2)^{2}(5a-3)$"}'::jsonb, 'A', '$(x-2)$ is a common factor of both terms, leaving $5a - 3$.', '{"B": "sign error on the second term", "C": "did not treat $(x-2)$ as a single factor", "D": "counted the common factor twice"}'::jsonb),
  ('factoring-common-factor--4-3', 'factoring-common-factor', 'eysh', 3, 'Factorise fully $8x^{3}y - 2xy^{3}$.', '{"A": "$2xy(2x-y)(2x+y)$", "B": "$2xy(4x^{2}-y^{2})$", "C": "$2xy(2x-y)^{2}$", "D": "$xy(8x^{2}-2y^{2})$"}'::jsonb, 'A', 'Take out $2xy$ to get $2xy(4x^{2}-y^{2})$, then the bracket is a difference of two squares: $2xy(2x-y)(2x+y)$.', '{"B": "stopped before factorising the difference of squares", "C": "used $(2x-y)^{2}$, which is not a difference of squares", "D": "took out only $xy$"}'::jsonb),
  ('like-terms-and-distribution--2-1', 'like-terms-and-distribution', 'eysh', 1, 'Simplify $3(2x - 5) - 2(x - 4)$.', '{"A": "$4x - 7$", "B": "$4x - 23$", "C": "$8x - 7$", "D": "$4x + 7$"}'::jsonb, 'A', '$6x - 15 - 2x + 8 = 4x - 7$.', '{"B": "did not change the sign of $-4$ when distributing $-2$", "C": "added the coefficients of $x$ instead of subtracting", "D": "sign slip on the constant"}'::jsonb),
  ('like-terms-and-distribution--3-2', 'like-terms-and-distribution', 'eysh', 2, 'Expand and simplify $(2x-3)(x+4) - 2x^{2}$.', '{"A": "$5x - 12$", "B": "$5x + 12$", "C": "$4x^{2}+5x-12$", "D": "$-5x-12$"}'::jsonb, 'A', '$(2x-3)(x+4) = 2x^{2}+5x-12$, and subtracting $2x^{2}$ leaves $5x-12$.', '{"B": "sign error on the constant term", "C": "added $2x^{2}$ instead of subtracting", "D": "sign error on the $x$ term"}'::jsonb),
  ('like-terms-and-distribution--4-3', 'like-terms-and-distribution', 'eysh', 3, 'Simplify $2a - \big[3b - (a - 2b)\big]$.', '{"A": "$3a - 5b$", "B": "$3a - b$", "C": "$a - 5b$", "D": "$3a + 5b$"}'::jsonb, 'A', 'Inner bracket first: $3b - (a-2b) = 3b - a + 2b = 5b - a$. Then $2a - (5b - a) = 3a - 5b$.', '{"B": "did not change the sign of $-2b$ in the inner bracket", "C": "dropped the sign change on $a$", "D": "sign error on the whole bracket"}'::jsonb),
  ('quadratic-by-factoring--2-1', 'quadratic-by-factoring', 'eysh', 1, 'Solve $x^{2} - 5x = 0$.', '{"A": "$x = 0$ or $x = 5$", "B": "$x = 5$", "C": "$x = -5$ or $x = 0$", "D": "$x = 5$ or $x = -5$"}'::jsonb, 'A', '$x(x-5)=0$, so $x=0$ or $x=5$.', '{"B": "divided both sides by $x$ and lost the root $x=0$", "C": "sign error factoring", "D": "treated it as a difference of squares"}'::jsonb),
  ('quadratic-by-factoring--3-2', 'quadratic-by-factoring', 'eysh', 2, 'Solve $x^{2} + 2x - 15 = 0$.', '{"A": "$x = 3$ or $x = -5$", "B": "$x = -3$ or $x = 5$", "C": "$x = 3$ or $x = 5$", "D": "$x = -3$ or $x = -5$"}'::jsonb, 'A', '$(x-3)(x+5)=0$, so $x=3$ or $x=-5$.', '{"B": "read the roots straight off the brackets without flipping the signs", "C": "both roots positive — product would be $+15$ with sum $8$", "D": "both roots negative — sum would be $-8$"}'::jsonb),
  ('quadratic-by-factoring--4-3', 'quadratic-by-factoring', 'eysh', 3, 'Solve $3x^{2} = 10x - 8$.', '{"A": "$x = 2$ or $x = \\dfrac43$", "B": "$x = -2$ or $x = -\\dfrac43$", "C": "$x = 2$ or $x = \\dfrac34$", "D": "$x = 4$ or $x = \\dfrac23$"}'::jsonb, 'A', 'Rearrange to $3x^{2}-10x+8=0$, factorise $(3x-4)(x-2)=0$, so $x=\tfrac43$ or $x=2$.', '{"B": "moved the terms without changing their signs", "C": "inverted the fractional root", "D": "misread the factor as $(x-4)(3x-2)$"}'::jsonb),
  ('quadratic-inequalities--2-1', 'quadratic-inequalities', 'eysh', 1, 'Solve $x^{2} - 9 > 0$.', '{"A": "$x < -3$ or $x > 3$", "B": "$-3 < x < 3$", "C": "$x > 3$", "D": "$x > 9$"}'::jsonb, 'A', '$(x-3)(x+3)>0$ holds outside the roots: $x<-3$ or $x>3$.', '{"B": "took the inside of the roots", "C": "kept only the positive branch", "D": "did not take the square root"}'::jsonb),
  ('quadratic-inequalities--3-2', 'quadratic-inequalities', 'eysh', 2, 'Solve $x^{2} + x - 6 \le 0$.', '{"A": "$-3 \\le x \\le 2$", "B": "$-2 \\le x \\le 3$", "C": "$x \\le -3$ or $x \\ge 2$", "D": "$-3 < x < 2$"}'::jsonb, 'A', '$(x+3)(x-2)\le 0$, so $x$ lies between the roots, endpoints included: $-3 \le x \le 2$.', '{"B": "sign error reading the roots off the factors", "C": "took the outside of the roots", "D": "excluded the endpoints although the inequality is not strict"}'::jsonb),
  ('quadratic-inequalities--4-3', 'quadratic-inequalities', 'eysh', 3, 'Solve $-x^{2} + 4x - 3 > 0$.', '{"A": "$1 < x < 3$", "B": "$x < 1$ or $x > 3$", "C": "$-3 < x < -1$", "D": "$1 \\le x \\le 3$"}'::jsonb, 'A', 'Multiply by $-1$ and flip: $x^{2}-4x+3<0$, i.e. $(x-1)(x-3)<0$, so $1<x<3$.', '{"B": "did not flip the inequality when multiplying by $-1$", "C": "flipped the signs of the roots as well", "D": "included the endpoints although the inequality is strict"}'::jsonb),
  ('special-products--2-1', 'special-products', 'eysh', 1, 'Expand $(2x - 5)^{2}$.', '{"A": "$4x^{2} - 20x + 25$", "B": "$4x^{2} + 25$", "C": "$4x^{2} - 10x + 25$", "D": "$2x^{2} - 20x + 25$"}'::jsonb, 'A', '$(a-b)^{2} = a^{2} - 2ab + b^{2}$ with $a=2x$, $b=5$: $4x^{2}-20x+25$.', '{"B": "squared each term and dropped the middle term", "C": "used $ab$ instead of $2ab$", "D": "did not square the coefficient $2$"}'::jsonb),
  ('special-products--3-2', 'special-products', 'eysh', 2, 'Simplify $(x+7)(x-7)$.', '{"A": "$x^{2} - 49$", "B": "$x^{2} + 49$", "C": "$x^{2} - 14x - 49$", "D": "$x^{2} - 14$"}'::jsonb, 'A', 'A difference of two squares: $x^{2} - 7^{2} = x^{2} - 49$.', '{"B": "sign error — the product of $+7$ and $-7$ is negative", "C": "kept a middle term that cancels", "D": "did not square the $7$"}'::jsonb),
  ('special-products--4-3', 'special-products', 'eysh', 3, 'Given $a + b = 7$ and $ab = 10$, find $a^{2} + b^{2}$.', '{"A": "$29$", "B": "$49$", "C": "$69$", "D": "$39$"}'::jsonb, 'A', '$a^{2}+b^{2} = (a+b)^{2} - 2ab = 49 - 20 = 29$.', '{"B": "used $(a+b)^{2}$ directly", "C": "added $2ab$ instead of subtracting", "D": "subtracted $ab$ rather than $2ab$"}'::jsonb),
  ('systems-two-linear--2-1', 'systems-two-linear', 'eysh', 1, 'Solve $\begin{cases} 3x + 2y = 16 \\ x = 2y \end{cases}$', '{"A": "$(4,\\ 2)$", "B": "$(2,\\ 4)$", "C": "$(4,\\ 4)$", "D": "$(8,\\ 4)$"}'::jsonb, 'A', 'Substituting $x=2y$: $6y + 2y = 16$, so $y = 2$ and $x = 4$.', '{"B": "wrote the pair in the wrong order", "C": "solved for $y$ then reused it as $x$", "D": "doubled $x$ a second time after substituting"}'::jsonb),
