  ('systems-two-linear--4-3', 'systems-two-linear', 'eysh', 3, 'For which value of $k$ does $\begin{cases} kx + 2y = 6 \\ 3x + y = 4 \end{cases}$ have NO solution?', '{"A": "$k = 6$", "B": "$k = \\dfrac{3}{2}$", "C": "$k = 3$", "D": "$k = 12$"}'::jsonb, 'A', 'No solution means the lines are parallel but not identical: $\dfrac{k}{3} = \dfrac{2}{1}$ gives $k=6$, and the constants then disagree.', '{"B": "inverted the ratio of the coefficients", "C": "matched $k$ to the coefficient of $x$ in the other equation", "D": "matched the constant terms instead of the coefficients"}'::jsonb),
  ('vieta-formulas--2-1', 'vieta-formulas', 'eysh', 1, 'The equation $x^{2} - 7x + 12 = 0$ has roots $x_{1}$, $x_{2}$. Find $x_{1}x_{2}$.', '{"A": "$12$", "B": "$7$", "C": "$-12$", "D": "$-7$"}'::jsonb, 'A', 'The product of the roots is $\dfrac{c}{a} = 12$.', '{"B": "gave the sum instead of the product", "C": "used $-\\dfrac{c}{a}$", "D": "used $-\\dfrac{b}{a}$ with the wrong sign"}'::jsonb),
  ('vieta-formulas--3-2', 'vieta-formulas', 'eysh', 2, 'The equation $3x^{2} + 5x - 2 = 0$ has roots $x_{1}$, $x_{2}$. Find $x_{1}+x_{2}$.', '{"A": "$-\\dfrac{5}{3}$", "B": "$\\dfrac{5}{3}$", "C": "$-\\dfrac{2}{3}$", "D": "$\\dfrac{2}{3}$"}'::jsonb, 'A', 'Sum of roots $= -\dfrac{b}{a} = -\dfrac{5}{3}$ (the roots are $\tfrac13$ and $-2$).', '{"B": "dropped the minus sign in $-\\tfrac{b}{a}$", "C": "gave the product $\\tfrac{c}{a}$", "D": "gave the product with the wrong sign"}'::jsonb),
  ('vieta-formulas--4-3', 'vieta-formulas', 'eysh', 3, 'The roots of $x^{2} - 6x + k = 0$ satisfy $x_{1}^{2} + x_{2}^{2} = 20$. Find $k$.', '{"A": "$8$", "B": "$16$", "C": "$-8$", "D": "$28$"}'::jsonb, 'A', '$x_{1}^{2}+x_{2}^{2} = (x_{1}+x_{2})^{2} - 2x_{1}x_{2} = 36 - 2k = 20$, so $k = 8$.', '{"B": "solved $36 - k = 20$", "C": "sign error rearranging", "D": "added $2k$ instead of subtracting"}'::jsonb),
  ('binomial-distribution--2-1', 'binomial-distribution', 'eysh', 1, 'A fair coin is tossed $4$ times. Find the probability of exactly $2$ heads.', '{"A": "$\\dfrac{3}{8}$", "B": "$\\dfrac{1}{4}$", "C": "$\\dfrac{1}{2}$", "D": "$\\dfrac{3}{16}$"}'::jsonb, 'A', '$\binom{4}{2}\left(\tfrac12\right)^{4} = \dfrac{6}{16} = \dfrac38$.', '{"B": "used $\\tfrac{2}{4}$ of the tosses as the probability", "C": "assumed exactly half is as likely as not", "D": "forgot the factor $\\binom{4}{2}$ and used $3$"}'::jsonb),
  ('binomial-distribution--3-2', 'binomial-distribution', 'eysh', 2, 'A biased die shows a six with probability $\tfrac13$. It is rolled $5$ times. Find the probability of exactly two sixes.', '{"A": "$\\dfrac{80}{243}$", "B": "$\\dfrac{40}{243}$", "C": "$\\dfrac{10}{243}$", "D": "$\\dfrac{80}{81}$"}'::jsonb, 'A', '$\binom{5}{2}\left(\tfrac13\right)^{2}\left(\tfrac23\right)^{3} = 10 \cdot \tfrac19 \cdot \tfrac{8}{27} = \dfrac{80}{243}$.', '{"B": "used $\\binom{5}{1}$ instead of $\\binom{5}{2}$, halving the count", "C": "omitted the $\\left(\\tfrac23\\right)^{3}$ factor", "D": "used the wrong power of the denominator"}'::jsonb),
  ('binomial-distribution--4-3', 'binomial-distribution', 'eysh', 3, 'A fair die is rolled $4$ times. Find the probability of at least one six.', '{"A": "$\\dfrac{671}{1296}$", "B": "$\\dfrac{625}{1296}$", "C": "$\\dfrac{2}{3}$", "D": "$\\dfrac{1}{1296}$"}'::jsonb, 'A', '$1 - \left(\tfrac56\right)^{4} = 1 - \dfrac{625}{1296} = \dfrac{671}{1296}$.', '{"B": "gave the probability of NO six", "C": "added $\\tfrac16$ four times", "D": "gave the probability of four sixes"}'::jsonb),
  ('conditional-probability--2-1', 'conditional-probability', 'eysh', 1, '$P(A \cap B) = 0.12$ and $P(B) = 0.4$. Find $P(A \mid B)$.', '{"A": "$0.3$", "B": "$0.048$", "C": "$0.28$", "D": "$0.52$"}'::jsonb, 'A', '$P(A \mid B) = \dfrac{P(A \cap B)}{P(B)} = \dfrac{0.12}{0.4} = 0.3$.', '{"B": "multiplied instead of dividing", "C": "subtracted instead of dividing", "D": "added instead of dividing"}'::jsonb),
  ('conditional-probability--3-2', 'conditional-probability', 'eysh', 2, 'Two cards are drawn without replacement from a standard pack of $52$. Find the probability that both are aces.', '{"A": "$\\dfrac{1}{221}$", "B": "$\\dfrac{1}{169}$", "C": "$\\dfrac{3}{676}$", "D": "$\\dfrac{1}{26}$"}'::jsonb, 'A', '$\dfrac{4}{52} \times \dfrac{3}{51} = \dfrac{1}{221}$ — the second draw sees one fewer ace and one fewer card.', '{"B": "treated the draws as WITH replacement", "C": "reduced the aces but not the pack size", "D": "gave the probability of one ace"}'::jsonb),
  ('conditional-probability--4-3', 'conditional-probability', 'eysh', 3, 'A bag holds $3$ red and $2$ blue balls. Two are drawn without replacement. Given that the first is red, find the probability that the second is red.', '{"A": "$\\dfrac{1}{2}$", "B": "$\\dfrac{3}{5}$", "C": "$\\dfrac{2}{5}$", "D": "$\\dfrac{3}{10}$"}'::jsonb, 'A', 'After a red is removed, $2$ of the remaining $4$ balls are red, so the probability is $\tfrac24 = \tfrac12$.', '{"B": "ignored the conditioning and used the original proportion", "C": "used the blue proportion", "D": "gave $P(\\text{both red})$, not the conditional"}'::jsonb),
  ('antiderivative-trig-exp--2-1', 'antiderivative-trig-exp', 'eysh', 1, 'Find $\displaystyle\int \cos x\,dx$.', '{"A": "$\\sin x + C$", "B": "$-\\sin x + C$", "C": "$-\\cos x + C$", "D": "$\\tan x + C$"}'::jsonb, 'A', '$\dfrac{d}{dx}(\sin x) = \cos x$, so the antiderivative is $\sin x + C$.', '{"B": "used the derivative rule for cosine instead", "C": "integrated $\\sin x$ by mistake", "D": "confused with $\\sec^{2}x$"}'::jsonb),
