  ('limit-concept--3-2', 'limit-concept', 'eysh', 2, 'Evaluate $\displaystyle\lim_{x \to 3} \frac{x^{2}-9}{x^{2}-2x-3}$.', '{"A": "$\\dfrac{3}{2}$", "B": "$1$", "C": "$3$", "D": "$0$"}'::jsonb, 'A', '$\dfrac{(x-3)(x+3)}{(x-3)(x+1)} = \dfrac{x+3}{x+1} \to \dfrac{6}{4} = \dfrac32$.', '{"B": "cancelled the whole numerator against the denominator", "C": "substituted only into the numerator''s factor", "D": "read $\\tfrac00$ as $0$"}'::jsonb),
