  ('optimisation--2-1', 'optimisation', 'eysh', 1, 'A rectangle has perimeter $20$. Find its greatest possible area.', '{"A": "$25$", "B": "$24$", "C": "$100$", "D": "$20$"}'::jsonb, 'A', 'With $x + y = 10$ the area is $x(10-x)$, greatest at $x = 5$, giving $25$.', '{"B": "used a $4 \\times 6$ rectangle without checking it is the maximum", "C": "squared the perimeter", "D": "confused area with perimeter"}'::jsonb),
