  ('optimisation--4-3', 'optimisation', 'eysh', 3, 'Equal squares of side $x$ are cut from the corners of a $12 \times 12$ sheet and the sides folded up. Find the greatest volume of the open box.', '{"A": "$128$", "B": "$144$", "C": "$108$", "D": "$64$"}'::jsonb, 'A', '$V = x(12-2x)^{2}$ and $V'' = (12-2x)(12-6x) = 0$ gives $x = 2$ (as $x=6$ collapses the box), so $V = 2 \times 8^{2} = 128$.', '{"B": "used $x = 3$", "C": "used $x = 1$ and mis-multiplied", "D": "forgot to square the base edge"}'::jsonb),
  ('exponential-and-log-graphs--2-1', 'exponential-and-log-graphs', 'eysh', 1, 'Through which point does the graph of $y = 2^{x}$ pass?', '{"A": "$(0,\\ 1)$", "B": "$(1,\\ 0)$", "C": "$(0,\\ 0)$", "D": "$(0,\\ 2)$"}'::jsonb, 'A', '$2^{0} = 1$, so the curve passes through $(0,1)$.', '{"B": "swapped the coordinates", "C": "assumed it passes through the origin", "D": "used the base as the $y$-intercept"}'::jsonb),
  ('exponential-and-log-graphs--3-2', 'exponential-and-log-graphs', 'eysh', 2, 'State the horizontal asymptote of $y = 3^{x-1} + 2$.', '{"A": "$y = 2$", "B": "$y = 0$", "C": "$y = 3$", "D": "$x = 1$"}'::jsonb, 'A', 'As $x \to -\infty$, $3^{x-1} \to 0$, so $y \to 2$.', '{"B": "gave the asymptote before the vertical shift", "C": "used the base as the asymptote", "D": "gave the horizontal shift as a vertical asymptote"}'::jsonb),
  ('exponential-and-log-graphs--4-3', 'exponential-and-log-graphs', 'eysh', 3, 'State the domain of $y = \log_{2}(x-3)$ and its vertical asymptote.', '{"A": "$x > 3$, asymptote $x = 3$", "B": "$x > 0$, asymptote $x = 0$", "C": "$x > -3$, asymptote $x = -3$", "D": "$x \\ge 3$, asymptote $x = 3$"}'::jsonb, 'A', 'The argument must be positive: $x - 3 > 0$, so $x > 3$, and the curve runs down the line $x = 3$.', '{"B": "ignored the horizontal shift", "C": "shifted the wrong way", "D": "included $x=3$, where the logarithm is undefined"}'::jsonb),
  ('inverse-functions--2-1', 'inverse-functions', 'eysh', 1, '$f(x) = 3x - 6$. Find $f^{-1}(x)$.', '{"A": "$\\dfrac{x+6}{3}$", "B": "$\\dfrac{x-6}{3}$", "C": "$3x + 6$", "D": "$\\dfrac{1}{3x-6}$"}'::jsonb, 'A', 'Swap and solve: $x = 3y - 6$ gives $y = \dfrac{x+6}{3}$.', '{"B": "subtracted instead of adding when undoing $-6$", "C": "undid the operations without swapping", "D": "took the reciprocal instead of the inverse function"}'::jsonb),
  ('inverse-functions--3-2', 'inverse-functions', 'eysh', 2, '$f(x) = \dfrac{x+2}{x-1}$. Find $f^{-1}(3)$.', '{"A": "$\\dfrac{5}{2}$", "B": "$\\dfrac{5}{4}$", "C": "$5$", "D": "$\\dfrac{3}{2}$"}'::jsonb, 'A', '$f^{-1}(3)$ is the $x$ with $f(x)=3$: $x+2 = 3x-3$, so $x = \tfrac52$.', '{"B": "solved $x + 2 = 3(x+1)$", "C": "solved $x+2=3x-3$ but dropped the $2$", "D": "evaluated $f(3)$ instead"}'::jsonb),
  ('inverse-functions--4-3', 'inverse-functions', 'eysh', 3, '$f(x) = x^{2}+1$ for $x \ge 0$. Find $f^{-1}(x)$.', '{"A": "$\\sqrt{x-1}$", "B": "$\\sqrt{x}-1$", "C": "$\\sqrt{x+1}$", "D": "$(x-1)^{2}$"}'::jsonb, 'A', '$x = y^{2}+1$ gives $y = \sqrt{x-1}$, taking the positive root because $x \ge 0$ was imposed.', '{"B": "subtracted outside the root instead of inside", "C": "added instead of subtracting", "D": "squared instead of taking the root"}'::jsonb),
  ('angles-and-parallel-lines--2-1', 'angles-and-parallel-lines', 'eysh', 1, 'Angles $3x$ and $2x + 30^{\circ}$ lie on a straight line. Find $x$.', '{"A": "$30^{\\circ}$", "B": "$36^{\\circ}$", "C": "$25^{\\circ}$", "D": "$15^{\\circ}$"}'::jsonb, 'A', '$3x + 2x + 30 = 180$, so $5x = 150$ and $x = 30^{\circ}$.', '{"B": "used $5x = 180$", "C": "used $5x + 30 = 155$", "D": "used $90^{\\circ}$ instead of $180^{\\circ}$"}'::jsonb),
  ('angles-and-parallel-lines--3-2', 'angles-and-parallel-lines', 'eysh', 2, 'Two parallel lines are cut by a transversal. One angle is $(2x+10)^{\circ}$ and its corresponding angle is $(3x-20)^{\circ}$. Find $x$.', '{"A": "$30$", "B": "$6$", "C": "$38$", "D": "$2$"}'::jsonb, 'A', 'Corresponding angles are equal: $2x+10 = 3x-20$, so $x = 30$.', '{"B": "set the two expressions to sum to $180$ and slipped", "C": "solved $2x + 10 + 3x - 20 = 180$", "D": "subtracted the constants only"}'::jsonb),
  ('angles-and-parallel-lines--4-3', 'angles-and-parallel-lines', 'eysh', 3, 'Four angles $x$, $2x$, $3x$ and $4x$ meet at a point and fill it completely. Find $x$.', '{"A": "$36^{\\circ}$", "B": "$18^{\\circ}$", "C": "$45^{\\circ}$", "D": "$60^{\\circ}$"}'::jsonb, 'A', '$10x = 360^{\circ}$, so $x = 36^{\circ}$.', '{"B": "used $180^{\\circ}$ instead of $360^{\\circ}$", "C": "divided $360^{\\circ}$ by the number of angles", "D": "used $600^{\\circ}$ as the total"}'::jsonb),
  ('chords-and-power-of-a-point--2-1', 'chords-and-power-of-a-point', 'eysh', 1, 'Two chords of a circle cross inside it. One is cut into lengths $3$ and $8$, the other into $4$ and $x$. Find $x$.', '{"A": "$6$", "B": "$24$", "C": "$7$", "D": "$12$"}'::jsonb, 'A', 'The products of the two parts are equal: $3 \times 8 = 4x$, so $x = 6$.', '{"B": "gave the product $3 \\times 8$ itself", "C": "added rather than using the product rule", "D": "divided $24$ by $2$"}'::jsonb),
  ('chords-and-power-of-a-point--3-2', 'chords-and-power-of-a-point', 'eysh', 2, 'From an external point a tangent of length $6$ touches a circle, and a secant from the same point meets the circle first at distance $4$. Find the length of the FAR segment of the secant.', '{"A": "$5$", "B": "$9$", "C": "$8$", "D": "$2$"}'::jsonb, 'A', '$6^{2} = 4 \times (\text{whole secant})$ gives a whole secant of $9$, so the far segment is $9 - 4 = 5$.', '{"B": "gave the whole secant rather than the far segment", "C": "used $6^{2} = 4 + x$", "D": "divided $6^{2}$ by $4$ then halved"}'::jsonb),
  ('chords-and-power-of-a-point--4-3', 'chords-and-power-of-a-point', 'eysh', 3, 'Chords $AB$ and $CD$ meet at $P$ inside a circle with $AP = x$, $PB = x+2$, $CP = 3$ and $PD = 8$. Find $x$.', '{"A": "$4$", "B": "$6$", "C": "$-6$", "D": "$3$"}'::jsonb, 'A', '$x(x+2) = 24$, so $x^{2}+2x-24=0$ and $(x+6)(x-4)=0$. Only $x=4$ is a length.', '{"B": "took the wrong root''s magnitude", "C": "kept the negative root as a length", "D": "solved $x + 2 = 8 - 3$"}'::jsonb),
  ('coordinate-midpoint--2-1', 'coordinate-midpoint', 'eysh', 1, 'Find the midpoint of $(-3,\ 5)$ and $(7,\ 1)$.', '{"A": "$(2,\\ 3)$", "B": "$(5,\\ 2)$", "C": "$(2,\\ -2)$", "D": "$(10,\\ 6)$"}'::jsonb, 'A', '$\left(\dfrac{-3+7}{2},\ \dfrac{5+1}{2}\right) = (2,\ 3)$.', '{"B": "halved the differences instead of the sums", "C": "subtracted the $y$-coordinates", "D": "added without halving"}'::jsonb),
  ('coordinate-midpoint--3-2', 'coordinate-midpoint', 'eysh', 2, '$M(4,-1)$ is the midpoint of $A(1,3)$ and $B$. Find $B$.', '{"A": "$(7,\\ -5)$", "B": "$(2.5,\\ 1)$", "C": "$(7,\\ -1)$", "D": "$(-2,\\ 7)$"}'::jsonb, 'A', '$B = (2 \times 4 - 1,\ 2 \times (-1) - 3) = (7,\ -5)$.', '{"B": "found the midpoint of $A$ and $M$", "C": "doubled the $x$ but copied the $y$ from $M$", "D": "reflected $A$ in the origin instead"}'::jsonb),
  ('coordinate-midpoint--4-3', 'coordinate-midpoint', 'eysh', 3, '$P$ divides $AB$ in the ratio $1:3$, where $A(2,1)$ and $B(10,9)$. Find $P$.', '{"A": "$(4,\\ 3)$", "B": "$(8,\\ 7)$", "C": "$(6,\\ 5)$", "D": "$(4.5,\\ 3.5)$"}'::jsonb, 'A', '$P = A + \tfrac14(B-A) = (2+2,\ 1+2) = (4,\ 3)$.', '{"B": "used the ratio $3:1$ — measured from the wrong end", "C": "used the midpoint", "D": "used $\\tfrac13$ instead of $\\tfrac14$"}'::jsonb),
  ('line-circle-intersection--2-1', 'line-circle-intersection', 'eysh', 1, 'How many points does the line $y = 1$ share with the circle $x^{2}+y^{2}=25$?', '{"A": "$2$", "B": "$1$", "C": "$0$", "D": "infinitely many"}'::jsonb, 'A', 'Substituting gives $x^{2} = 24 > 0$, so there are two values of $x$.', '{"B": "treated the line as a tangent", "C": "thought $y=1$ lies outside the circle", "D": "confused the line with the circle itself"}'::jsonb),
  ('line-circle-intersection--3-2', 'line-circle-intersection', 'eysh', 2, 'For which values of $c$ is $y = x + c$ tangent to $x^{2}+y^{2}=8$?', '{"A": "$c = \\pm 4$", "B": "$c = \\pm 2\\sqrt{2}$", "C": "$c = \\pm 8$", "D": "$c = \\pm 4\\sqrt{2}$"}'::jsonb, 'A', 'Substituting gives $2x^{2}+2cx+c^{2}-8=0$; tangency needs $\Delta = 0$, i.e. $4c^{2}-8(c^{2}-8)=0$, so $c^{2}=16$ and $c=\pm4$.', '{"B": "used the radius $2\\sqrt{2}$ as the intercept", "C": "solved $c^{2}=64$", "D": "multiplied the radius by $2$"}'::jsonb),
  ('line-circle-intersection--4-3', 'line-circle-intersection', 'eysh', 3, 'Find the point(s) where $y = 2x - 5$ meets $x^{2}+y^{2}=5$.', '{"A": "$(2,\\ -1)$ only", "B": "$(2,\\ -1)$ and $(-2,\\ -9)$", "C": "$(1,\\ -3)$ only", "D": "they do not meet"}'::jsonb, 'A', '$x^{2}+(2x-5)^{2}=5$ reduces to $5(x-2)^{2}=0$, a repeated root at $x=2$: the line is a tangent, touching at $(2,-1)$.', '{"B": "assumed a quadratic always gives two distinct points", "C": "arithmetic slip solving for $x$", "D": "read the repeated root as no solution"}'::jsonb),
  ('parallel-perpendicular-lines--2-1', 'parallel-perpendicular-lines', 'eysh', 1, 'Find the gradient of a line perpendicular to $y = 3x + 1$.', '{"A": "$-\\dfrac{1}{3}$", "B": "$3$", "C": "$\\dfrac{1}{3}$", "D": "$-3$"}'::jsonb, 'A', 'Perpendicular gradients multiply to $-1$, so it is $-\tfrac13$.', '{"B": "gave the parallel gradient", "C": "took the reciprocal but not the negative", "D": "took the negative but not the reciprocal"}'::jsonb),
  ('parallel-perpendicular-lines--3-2', 'parallel-perpendicular-lines', 'eysh', 2, 'Find the equation of the line through $(2,5)$ parallel to $2x + y = 7$.', '{"A": "$y = -2x + 9$", "B": "$y = 2x + 1$", "C": "$y = -2x + 5$", "D": "$y = \\tfrac12 x + 4$"}'::jsonb, 'A', 'The gradient is $-2$, so $y - 5 = -2(x-2)$, i.e. $y = -2x+9$.', '{"B": "used $+2$ as the gradient", "C": "used the $y$-coordinate as the intercept", "D": "used the perpendicular gradient"}'::jsonb),
  ('parallel-perpendicular-lines--4-3', 'parallel-perpendicular-lines', 'eysh', 3, 'For which $k$ are $kx + 4y = 3$ and $2x - 3y = 1$ perpendicular?', '{"A": "$k = 6$", "B": "$k = -6$", "C": "$k = \\dfrac{8}{3}$", "D": "$k = \\dfrac{3}{2}$"}'::jsonb, 'A', 'The gradients are $-\dfrac{k}{4}$ and $\dfrac23$; their product is $-1$ when $k = 6$.', '{"B": "sign slip solving for $k$", "C": "set the gradients equal instead", "D": "inverted the second gradient"}'::jsonb),
  ('quadrilateral-properties--2-1', 'quadrilateral-properties', 'eysh', 1, 'One angle of a parallelogram is $65^{\circ}$. Find an adjacent angle.', '{"A": "$115^{\\circ}$", "B": "$65^{\\circ}$", "C": "$25^{\\circ}$", "D": "$130^{\\circ}$"}'::jsonb, 'A', 'Adjacent angles of a parallelogram are supplementary: $180^{\circ}-65^{\circ}$.', '{"B": "gave the opposite angle, which is the equal one", "C": "used the complement", "D": "doubled the given angle"}'::jsonb),
  ('quadrilateral-properties--3-2', 'quadrilateral-properties', 'eysh', 2, 'A rhombus has diagonals of length $6$ and $8$. Find its side length.', '{"A": "$5$", "B": "$10$", "C": "$7$", "D": "$\\sqrt{14}$"}'::jsonb, 'A', 'The diagonals bisect at right angles, so the side is $\sqrt{3^{2}+4^{2}} = 5$.', '{"B": "used the full diagonals instead of their halves", "C": "averaged the halves", "D": "added the halves before squaring"}'::jsonb),
  ('quadrilateral-properties--4-3', 'quadrilateral-properties', 'eysh', 3, 'A rectangle has perimeter $34$ and diagonal $13$. Find its area.', '{"A": "$60$", "B": "$120$", "C": "$72$", "D": "$30$"}'::jsonb, 'A', '$l+w = 17$ and $l^{2}+w^{2}=169$, so $2lw = 17^{2}-169 = 120$ and the area $lw = 60$ (the sides are $5$ and $12$).', '{"B": "stopped at $2lw$", "C": "guessed $6 \\times 12$", "D": "halved the area a second time"}'::jsonb),
  ('rotation--2-1', 'rotation', 'eysh', 1, 'Rotate the point $(3,0)$ by $90^{\circ}$ anticlockwise about the origin.', '{"A": "$(0,\\ 3)$", "B": "$(0,\\ -3)$", "C": "$(-3,\\ 0)$", "D": "$(3,\\ 0)$"}'::jsonb, 'A', '$(x,y) \mapsto (-y,\ x)$, so $(3,0) \mapsto (0,3)$.', '{"B": "rotated clockwise instead", "C": "rotated by $180^{\\circ}$", "D": "left the point unchanged"}'::jsonb),
  ('rotation--3-2', 'rotation', 'eysh', 2, 'Rotate the point $(2,5)$ by $180^{\circ}$ about the origin.', '{"A": "$(-2,\\ -5)$", "B": "$(5,\\ 2)$", "C": "$(-5,\\ -2)$", "D": "$(2,\\ -5)$"}'::jsonb, 'A', '$(x,y) \mapsto (-x,-y)$.', '{"B": "swapped the coordinates instead", "C": "swapped and negated", "D": "reflected in the $x$-axis"}'::jsonb),
  ('rotation--4-3', 'rotation', 'eysh', 3, 'Rotate the point $(1,2)$ by $90^{\circ}$ clockwise about the origin.', '{"A": "$(2,\\ -1)$", "B": "$(-2,\\ 1)$", "C": "$(2,\\ 1)$", "D": "$(-1,\\ 2)$"}'::jsonb, 'A', 'Clockwise: $(x,y) \mapsto (y,\ -x)$, so $(1,2) \mapsto (2,-1)$.', '{"B": "rotated anticlockwise", "C": "swapped without changing a sign", "D": "negated the wrong coordinate"}'::jsonb),
  ('special-right-triangles--2-1', 'special-right-triangles', 'eysh', 1, 'A right-angled isosceles triangle has legs of length $7$. Find the hypotenuse.', '{"A": "$7\\sqrt{2}$", "B": "$14$", "C": "$7\\sqrt{3}$", "D": "$\\dfrac{7}{\\sqrt{2}}$"}'::jsonb, 'A', '$\sqrt{7^{2}+7^{2}} = 7\sqrt{2}$.', '{"B": "doubled the leg", "C": "used the $30$–$60$–$90$ ratio", "D": "divided by $\\sqrt{2}$ instead of multiplying"}'::jsonb),
  ('special-right-triangles--3-2', 'special-right-triangles', 'eysh', 2, 'In a $30^{\circ}$–$60^{\circ}$–$90^{\circ}$ triangle the shortest side is $5$. Find the hypotenuse.', '{"A": "$10$", "B": "$5\\sqrt{3}$", "C": "$5\\sqrt{2}$", "D": "$10\\sqrt{3}$"}'::jsonb, 'A', 'The sides are in the ratio $1 : \sqrt3 : 2$, so the hypotenuse is $2 \times 5 = 10$.', '{"B": "gave the middle side", "C": "used the isosceles ratio", "D": "multiplied the middle side by $2$"}'::jsonb),
  ('special-right-triangles--4-3', 'special-right-triangles', 'eysh', 3, 'An equilateral triangle has side $6$. Find its height.', '{"A": "$3\\sqrt{3}$", "B": "$6\\sqrt{3}$", "C": "$3$", "D": "$3\\sqrt{2}$"}'::jsonb, 'A', 'The height splits the base in half: $\sqrt{6^{2}-3^{2}} = \sqrt{27} = 3\sqrt3$.', '{"B": "used the full side as the base of the right triangle", "C": "halved the side and stopped", "D": "used the isosceles ratio"}'::jsonb),
  ('trapezoid-properties--2-1', 'trapezoid-properties', 'eysh', 1, 'A trapezoid has parallel sides $7$ and $11$ and height $5$. Find its area.', '{"A": "$45$", "B": "$90$", "C": "$55$", "D": "$40$"}'::jsonb, 'A', '$\tfrac12(7+11)(5) = 45$.', '{"B": "omitted the factor $\\tfrac12$", "C": "used $11 \\times 5$", "D": "used the difference of the parallel sides"}'::jsonb),
  ('trapezoid-properties--3-2', 'trapezoid-properties', 'eysh', 2, 'A trapezoid has area $60$ and parallel sides $8$ and $12$. Find its height.', '{"A": "$6$", "B": "$3$", "C": "$12$", "D": "$\\dfrac{20}{3}$"}'::jsonb, 'A', '$\tfrac12(20)h = 60$ gives $10h = 60$, so $h = 6$.', '{"B": "forgot the $\\tfrac12$ when rearranging", "C": "divided by the smaller side", "D": "divided $60$ by $9$"}'::jsonb),
  ('trapezoid-properties--4-3', 'trapezoid-properties', 'eysh', 3, 'An isosceles trapezoid has parallel sides $10$ and $4$ and legs of length $5$. Find its height.', '{"A": "$4$", "B": "$5$", "C": "$3$", "D": "$\\sqrt{21}$"}'::jsonb, 'A', 'Each end overhangs by $\dfrac{10-4}{2}=3$, so the height is $\sqrt{5^{2}-3^{2}} = 4$.', '{"B": "used the leg as the height", "C": "gave the overhang instead of the height", "D": "used an overhang of $2$"}'::jsonb),
  ('data-representation--2-1', 'data-representation', 'eysh', 1, 'A frequency table records the values $1$, $2$, $3$ with frequencies $4$, $6$, $10$. Find the mean.', '{"A": "$2.3$", "B": "$2$", "C": "$6\\tfrac23$", "D": "$15\\tfrac13$"}'::jsonb, 'A', '$\dfrac{1(4)+2(6)+3(10)}{20} = \dfrac{46}{20} = 2.3$.', '{"B": "averaged the values, ignoring the frequencies", "C": "averaged the frequencies", "D": "divided by the number of values, not the total"}'::jsonb),
  ('data-representation--3-2', 'data-representation', 'eysh', 2, 'A histogram has three bars, each of width $10$, with frequency densities $0.4$, $1.2$ and $0.9$. Find the total frequency.', '{"A": "$25$", "B": "$2.5$", "C": "$250$", "D": "$30$"}'::jsonb, 'A', 'Frequency is density times width: $10(0.4+1.2+0.9) = 25$.', '{"B": "added the densities without multiplying by the width", "C": "multiplied by $100$", "D": "used a width of $12$"}'::jsonb),
  ('data-representation--4-3', 'data-representation', 'eysh', 3, 'A bar chart has four categories whose frequencies are in the ratio $2:3:4:1$, with total $60$. Find the largest frequency.', '{"A": "$24$", "B": "$6$", "C": "$18$", "D": "$30$"}'::jsonb, 'A', 'There are $2+3+4+1 = 10$ parts, so one part is $6$ and the largest is $4 \times 6 = 24$.', '{"B": "gave the size of one part", "C": "used the ratio $3$", "D": "halved the total"}'::jsonb),
  ('absolute-value-equations--2-1', 'absolute-value-equations', 'eysh', 1, 'Solve $|x - 3| = 7$.', '{"A": "$x = 10$ or $x = -4$", "B": "$x = 10$", "C": "$x = 4$ or $x = -4$", "D": "$x = 10$ or $x = 4$"}'::jsonb, 'A', '$x-3 = 7$ or $x-3 = -7$, giving $x = 10$ or $x = -4$.', '{"B": "took only the positive case", "C": "solved $|x| = \\pm 7$ then subtracted", "D": "sign slip on the negative case"}'::jsonb),
  ('absolute-value-equations--3-2', 'absolute-value-equations', 'eysh', 2, 'Solve $|2x + 1| = 9$.', '{"A": "$x = 4$ or $x = -5$", "B": "$x = 4$", "C": "$x = 4$ or $x = 5$", "D": "$x = -4$ or $x = 5$"}'::jsonb, 'A', '$2x+1 = 9$ gives $x=4$; $2x+1 = -9$ gives $x = -5$.', '{"B": "took only the positive case", "C": "sign slip on the negative case", "D": "negated both roots"}'::jsonb),
  ('absolute-value-equations--4-3', 'absolute-value-equations', 'eysh', 3, 'Solve $|x - 2| = 3x - 6$.', '{"A": "$x = 2$ only", "B": "$x = 2$ or $x = 1$", "C": "$x = 1$", "D": "no solution"}'::jsonb, 'A', 'The right side is $3(x-2)$, so with $u = x-2$: $|u| = 3u$, which forces $u \ge 0$ and then $u = 3u$, i.e. $u = 0$ and $x = 2$.', '{"B": "kept a root that makes the right-hand side negative", "C": "solved the negative case without checking it", "D": "rejected every root, including the valid one"}'::jsonb),
  ('absolute-value-inequalities--2-1', 'absolute-value-inequalities', 'eysh', 1, 'Solve $|x| < 5$.', '{"A": "$-5 < x < 5$", "B": "$x < 5$", "C": "$x < -5$ or $x > 5$", "D": "$-5 \\le x \\le 5$"}'::jsonb, 'A', '$|x|<5$ means $x$ is within $5$ of zero: $-5<x<5$.', '{"B": "kept only the positive half", "C": "solved $|x|>5$ instead", "D": "included the endpoints although the inequality is strict"}'::jsonb),
  ('absolute-value-inequalities--3-2', 'absolute-value-inequalities', 'eysh', 2, 'Solve $|x - 4| \ge 3$.', '{"A": "$x \\le 1$ or $x \\ge 7$", "B": "$1 \\le x \\le 7$", "C": "$x \\ge 7$", "D": "$-7 \\le x \\le -1$"}'::jsonb, 'A', '$x-4 \ge 3$ or $x-4 \le -3$, giving $x \ge 7$ or $x \le 1$.', '{"B": "solved the ''<'' version — this is the inside of the interval", "C": "kept only the positive case", "D": "negated the endpoints"}'::jsonb),
  ('absolute-value-inequalities--4-3', 'absolute-value-inequalities', 'eysh', 3, 'Solve $|2x - 1| < 5$.', '{"A": "$-2 < x < 3$", "B": "$-3 < x < 2$", "C": "$x < -2$ or $x > 3$", "D": "$-2 \\le x \\le 3$"}'::jsonb, 'A', '$-5 < 2x-1 < 5$ gives $-4 < 2x < 6$, so $-2 < x < 3$.', '{"B": "divided before adding $1$", "C": "solved the ''>'' version", "D": "included the endpoints although the inequality is strict"}'::jsonb),
  ('completing-the-square--2-1', 'completing-the-square', 'eysh', 1, 'Write $x^{2} + 6x + 5$ in the form $(x+p)^{2}+q$.', '{"A": "$(x+3)^{2} - 4$", "B": "$(x+3)^{2} + 5$", "C": "$(x+6)^{2} - 31$", "D": "$(x+3)^{2} - 9$"}'::jsonb, 'A', '$(x+3)^{2} = x^{2}+6x+9$, so $x^{2}+6x+5 = (x+3)^{2} - 9 + 5 = (x+3)^{2}-4$.', '{"B": "did not subtract the $9$ that was added", "C": "halved nothing — used the whole coefficient of $x$", "D": "subtracted the $9$ but forgot the $+5$"}'::jsonb),
  ('completing-the-square--3-2', 'completing-the-square', 'eysh', 2, 'Write $x^{2} - 8x + 3$ in the form $(x+p)^{2}+q$.', '{"A": "$(x-4)^{2} - 13$", "B": "$(x-4)^{2} + 3$", "C": "$(x-8)^{2} - 61$", "D": "$(x-4)^{2} - 19$"}'::jsonb, 'A', '$(x-4)^{2} = x^{2}-8x+16$, so the expression is $(x-4)^{2} - 16 + 3 = (x-4)^{2}-13$.', '{"B": "did not subtract the $16$", "C": "used the whole coefficient instead of half", "D": "subtracted $16$ and $3$ instead of adding the $3$"}'::jsonb),
