  ('log-product-rule--2-1', 'log-product-rule', 'eysh', 1, 'Evaluate $\log 4 + \log 25$ (base $10$).', '{"A": "$2$", "B": "$\\log 29$", "C": "$100$", "D": "$1$"}'::jsonb, 'A', '$\log 4 + \log 25 = \log 100 = 2$.', '{"B": "added the arguments instead of multiplying them", "C": "stopped at $\\log 100$ and reported the argument", "D": "used $\\log 10$"}'::jsonb),
  ('log-product-rule--3-2', 'log-product-rule', 'eysh', 2, 'Evaluate $\log_{3} 9 + \log_{3} 27$.', '{"A": "$5$", "B": "$6$", "C": "$\\log_{3} 36$", "D": "$36$"}'::jsonb, 'A', '$\log_{3}(9 \times 27) = \log_{3}243 = 5$; equivalently $2 + 3 = 5$.', '{"B": "multiplied the two logarithms", "C": "added the arguments", "D": "added the arguments and did not take the logarithm"}'::jsonb),
  ('log-product-rule--4-3', 'log-product-rule', 'eysh', 3, 'Solve $\log_{2} x + \log_{2}(x+6) = 4$.', '{"A": "$x = 2$", "B": "$x = 2$ or $x = -8$", "C": "$x = -8$", "D": "$x = 10$"}'::jsonb, 'A', '$\log_{2}\big(x(x+6)\big) = 4$ gives $x^{2}+6x-16=0$, i.e. $(x+8)(x-2)=0$. Only $x = 2$ keeps both logarithms defined.', '{"B": "did not reject the root outside the domain", "C": "kept the rejected root", "D": "added the arguments instead of multiplying"}'::jsonb),
  ('change-of-base--2-1', 'change-of-base', 'eysh', 1, 'Express $\log_{8} 32$ in base $2$ and evaluate it.', '{"A": "$\\dfrac{5}{3}$", "B": "$\\dfrac{3}{5}$", "C": "$4$", "D": "$\\dfrac{32}{8}$"}'::jsonb, 'A', '$\log_{8}32 = \dfrac{\log_{2}32}{\log_{2}8} = \dfrac{5}{3}$.', '{"B": "inverted the fraction", "C": "divided the arguments", "D": "divided the numbers rather than their logarithms"}'::jsonb),
  ('change-of-base--3-2', 'change-of-base', 'eysh', 2, 'Evaluate $\log_{4} 8$.', '{"A": "$\\dfrac{3}{2}$", "B": "$2$", "C": "$\\dfrac{2}{3}$", "D": "$32$"}'::jsonb, 'A', '$\dfrac{\log_{2}8}{\log_{2}4} = \dfrac{3}{2}$.', '{"B": "used $8 \\div 4$", "C": "inverted the fraction", "D": "multiplied the arguments"}'::jsonb),
  ('change-of-base--4-3', 'change-of-base', 'eysh', 3, 'Given $\log_{10} 2 \approx 0.301$, evaluate $\log_{2} 10$ to $3$ significant figures.', '{"A": "$3.32$", "B": "$0.301$", "C": "$0.699$", "D": "$2.99$"}'::jsonb, 'A', '$\log_{2}10 = \dfrac{1}{\log_{10}2} \approx \dfrac{1}{0.301} \approx 3.32$.', '{"B": "returned the given value unchanged", "C": "computed $1 - 0.301$", "D": "computed $1 \\div 0.301$ but mis-divided"}'::jsonb),
  ('log-quotient-rule--2-1', 'log-quotient-rule', 'eysh', 1, 'Evaluate $\log 200 - \log 2$ (base $10$).', '{"A": "$2$", "B": "$\\log 198$", "C": "$100$", "D": "$1$"}'::jsonb, 'A', '$\log\dfrac{200}{2} = \log 100 = 2$.', '{"B": "subtracted the arguments instead of dividing them", "C": "reported the argument rather than the logarithm", "D": "divided by $20$"}'::jsonb),
  ('log-quotient-rule--3-2', 'log-quotient-rule', 'eysh', 2, 'Evaluate $\log_{5} 100 - \log_{5} 4$.', '{"A": "$2$", "B": "$96$", "C": "$\\log_{5} 96$", "D": "$25$"}'::jsonb, 'A', '$\log_{5}\dfrac{100}{4} = \log_{5}25 = 2$.', '{"B": "subtracted the arguments and dropped the logarithm", "C": "subtracted the arguments", "D": "reported the argument"}'::jsonb),
  ('log-quotient-rule--4-3', 'log-quotient-rule', 'eysh', 3, 'Given $\log a = 1.2$ and $\log b = 0.5$, find $\log\dfrac{a}{b}$.', '{"A": "$0.7$", "B": "$1.7$", "C": "$2.4$", "D": "$0.6$"}'::jsonb, 'A', '$\log\dfrac{a}{b} = \log a - \log b = 1.2 - 0.5 = 0.7$.', '{"B": "added the logarithms — that is $\\log(ab)$", "C": "divided $1.2$ by $0.5$", "D": "multiplied the logarithms"}'::jsonb)
